public class InjectionMetadata {

    private final Class<?> targetClass;
    private final Collection<InjectedElement> checkedElements;

    public InjectionMetadata(Class<?> targetClass, Collection<InjectedElement> elements) {
        this.targetClass = targetClass;
        this.checkedElements = elements;
    }

    public void inject(Object target, String beanName, PropertyValues pvs) throws Throwable {
        ReflectionUtils.doWithLocalFields(targetClass, field -> {
            InjectedElement element = findInjectedElement(targetClass, field);
            if (element != null) {
                element.inject(target, beanName, pvs);
            }
        });
        ReflectionUtils.doWithLocalMethods(targetClass, method -> {
            method = BridgeMethodResolver.findBridgedMethod(method);
            InjectedElement element = findInjectedElement(targetClass, method);
            if (element != null) {
                element.inject(target, beanName, pvs);
            }
        });
    }
}
